SOURCE_PHRASES = json.loads(r'''{"1":{"23":"Les Anges aiment que les hommes respirent les vertus"},"2":{"8":"Le monde divin répond toujours à la prière entendue"},"3":{"12":"La période de Raphaël"},"4":{"1":"La pierre verte"},"5":{"16":"d’incarnation en incarnation"},"6":{"7":"modes"},"7":{"5":"passivité"},"8":{"2":"nourriture"},"9":{"17":"l’esprit de l’air"},"10":{"22":"soutien mutuel"},"11":{"3":"phénix"},"12":{"12":"jardin de paradis"},"13":{"6":"dignité"},"14":{"5":"clarté dans la pensée"},"15":{"19":"le mariage parfait"},"16":{"6":"l’aigle est un messager du soleil"},"17":{"2":"en correspondance"},"18":{"2":"temple de la méditation"},"19":{"3":"océan d’éther"},"20":{"2":"flamme sacrée de l’enthousiasme"},"21":{"8":"papillon"},"22":{"2":"mémoire de ton âme"},"23":{"13":"souffle pur"}}''')

def load(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))

def normalize(value: str) -> str:
    s = unicodedata.normalize("NFKD", str(value or ""))
    s = "".join(c for c in s if not unicodedata.combining(c)).casefold()
    return re.sub(r"[^a-z0-9]+", " ", s.replace("œ", "oe").replace("æ", "ae")).strip()

def verify() -> None:
    book = load(INDEX / "books/book-03.json")
    directory = load(INDEX / "theme-directory.json")
    public = load(INDEX / "theme-directory-public.json")
    runtime = load(INDEX / "theme-search-runtime.json")
    assert book["book"]["number"] == 3 and book["book"]["archangel"] == "raphael"
    assert len(book["psalmAnalyses"]) == 23
    assert set(BASELINE) == set(NEW_VERSES) == set(SOURCE_PHRASES) == {str(i) for i in range(1,24)}
    canonical = {t["id"]: t for t in directory["themes"]}
    exposed = {t["id"]: t for t in public["themes"]}
    assert set(canonical) == set(exposed)
    assert len(canonical) == directory["themeCount"] == public["themeCount"] == runtime["themeCount"]
    assert len(canonical) == 1267, len(canonical)
    assert runtime["aliasCount"] == 1362, runtime["aliasCount"]
    source_verse_count = original_count = addition_count = 0
    for n in range(1,24):
        a = book["psalmAnalyses"][n-1]
        src = load(CORPUS / f"psalm-{n:03d}.json")
        assert a["number"] == n and src["id"] == a["recordId"] == f"book-03-psalm-{n:03d}"
        assert a["title"] == src["title"]
        verses = {int(v["number"]):v["text"] for v in src["verses"]}
        source_verse_count += len(verses)
        for vno, phrase in SOURCE_PHRASES[str(n)].items():
            assert normalize(phrase) in normalize(verses[int(vno)]), (n, vno, phrase)
        historical = BASELINE[str(n)]
        additional = NEW_VERSES[str(n)]
        assert set(historical).isdisjoint(additional)
        theme_relations = a["themes"]
        found = {t["themeId"]:t for t in theme_relations}
        assert len(found) == len(theme_relations), (n,"duplicate theme id")
        assert set(found) == set(historical) | set(additional), (n,"missing, replaced or unreviewed relation")
        original_count += len(historical)
        addition_count += len(additional)
        for id_, historical_values in historical.items():
            rel = found[id_]
            assert {k:rel[k] for k in historical_values} == historical_values, (n,id_,"historical relation changed")
        for id_, checked in additional.items():
            rel = found[id_]
            assert rel["verseNumbers"] == checked, (n,id_,"new verse anchors drift")
            assert rel["teaching"].startswith("La Bible essénienne enseigne que "), (n,id_)
        for id_,rel in found.items():
            anchors = rel["verseNumbers"]
            assert anchors and all(v in verses for v in anchors), (n,id_,"verse outside canonical text")
            assert rel["importance"] in {"central","important","related"}
            assert rel["directness"] in {"direct","symbolic","contextual","editorial","indirect"}
            for thematic in (canonical,exposed):
                assert id_ in thematic,(n,id_,"missing theme id")
                occurrences = [o for o in thematic[id_]["occurrences"] if o["recordId"] == src["id"]]
                assert len(occurrences) == 1,(n,id_,"missing/duplicate browser occurrence")
                for field in ("verseNumbers","teaching","importance"):
                    assert occurrences[0][field] == rel[field], (n,id_,field,"canonical/public mismatch")
    assert source_verse_count == 344, source_verse_count
    assert original_count == 80, original_count
    assert addition_count == 319, addition_count
    for id_,label in (("conformisme","Conformisme"),("ignorance","Ignorance")):
        assert id_ in canonical and id_ in exposed
        alias = runtime["aliases"].get(normalize(label))
        assert alias and id_ in alias["themeIds"],(id_,label,"not searchable")
        assert any(o["recordId"] == "book-03-psalm-006" for o in exposed[id_]["occurrences"])
    audits = book["method"].get("themeCoverageAudits")
    assert isinstance(audits,list) and len(audits)==1
    scope = audits[0]
    assert scope["scope"] == "book-03-psalms-001-023"
    assert scope["originalRelationCount"] == 80 and scope["addedRelationCount"] == 319
    assert scope["verifiedVerseCount"] == 344
    assert scope["sourcePsalmsModified"] is False
    print("BIBLAW BOOK 03 FULL AUDIT PASS: 23 Psalms / 344 source verses / 80 historical links unchanged + 319 evidenced links / 2 new searchable concepts / 1267 public themes.")


if __name__ == "__main__":
    verify()
